{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, count(*) n, round(approx_quantile(p.duration/1e6,0.5),1) parent_p50_ms, round(approx_quantile((p.duration - coalesce(c.cd,0))/1e6,0.5),1) unexplained_p50_ms, round(approx_quantile(c.cd/1e6,0.5),1) child_client_p50_ms FROM (SELECT 'abn' src, span_id, duration, service_name, span_name FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='Travel2Controller.queryInfo' UNION ALL SELECT 'norm', span_id, duration, service_name, span_name FROM normal_traces WHERE service_name='ts-travel2-service' AND span_name='Travel2Controller.queryInfo') p LEFT JOIN (SELECT parent_span_id, sum(duration) cd FROM (SELECT parent_span_id, duration, attr_span_kind FROM abnormal_traces UNION ALL SELECT parent_span_id, duration, attr_span_kind FROM normal_traces) WHERE attr_span_kind='Client' GROUP BY 1) c ON c.parent_span_id = p.span_id GROUP BY src",
          "claim": "travel2 queryInfo p50 rises from 86ms to 11066ms; unexplained time outside child client calls rises from 9.5ms to 10930ms, while child client calls stay ~76-116ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.5) p50, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name='ts-travel2-service' GROUP BY 1,2 ORDER BY 1",
          "claim": "In abnormal period travel2 DB spans (TripRepository.findAll ~3ms p50) stay fast while its POST /trips/left server span p50 is ~11s."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name IN ('ts-route-plan-service','ts-travel-plan-service','ts-ui-dashboard') AND span_name LIKE '%travel%' GROUP BY 1,2,3 ORDER BY 2,3",
          "claim": "Route-plan and travel-plan server spans for travel plan paths rise to 20-26s p95 in abnormal period, consistent with waiting on travel2."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name IN ('ts-route-plan-service','ts-travel-plan-service','ts-ui-dashboard') AND span_name LIKE '%travel%' GROUP BY 1,2,3 ORDER BY 2,3",
          "claim": "Travel-plan quickest/cheapest/minStation server spans rise to ~22-26s p95, while route-plan's own work stays small."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name IN ('ts-route-plan-service','ts-travel-plan-service','ts-ui-dashboard') AND span_name LIKE '%travel%' GROUP BY 1,2,3 ORDER BY 2,3",
          "claim": "ui-dashboard travelPlan endpoints show p95 of ~20s in abnormal period, matching the slowdown passed up from travel-plan."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95 FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name = 'ts-ui-dashboard' AND span_name LIKE '%travel2%' GROUP BY 1,2,3",
          "claim": "ui-dashboard's direct POST /api/v1/travel2service/trips/left calls show p95 of about 19.3s in abnormal period versus about 0.95s normally."
        }
      ]
    }
  ]
}
